  -- Signals
  SIGNAL init_guard_true_1                : std_logic;
  SIGNAL init_guard_true_2                : std_logic;
  SIGNAL outinit_guard_default_re         : signed(17 DOWNTO 0);  -- sfix18_En16
  SIGNAL outinit_guard_default_im         : signed(17 DOWNTO 0);  -- sfix18_En16
  SIGNAL count_step                       : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL count_from                       : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL count_reset                      : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL HDL_Counter_out1                 : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL count                            : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL need_to_wrap                     : std_logic;
  SIGNAL count_value                      : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL count_1                          : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL count_2                          : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL prelookup_idx_sat                : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL prelookup_idx                    : unsigned(12 DOWNTO 0);  -- ufix13
  SIGNAL realOut                          : signed(17 DOWNTO 0);  -- sfix18_En16
  SIGNAL realOut_1                        : signed(17 DOWNTO 0) := to_signed(16#00000#, 18);  -- sfix18_En16
  SIGNAL imagOut                          : signed(17 DOWNTO 0);  -- sfix18_En16
  SIGNAL imagOut_1                        : signed(17 DOWNTO 0) := to_signed(16#00000#, 18);  -- sfix18_En16
  SIGNAL alpha1_D_Lookup_Table_out1_re    : signed(17 DOWNTO 0);  -- sfix18_En16
  SIGNAL alpha1_D_Lookup_Table_out1_im    : signed(17 DOWNTO 0);  -- sfix18_En16
  SIGNAL Compare_To_Constant_out1         : std_logic;

BEGIN
  init_guard_true_1 <= '1';

  matching_delays_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        init_guard_true_2 <= '0';
      ELSIF enb_1_32_0 = '1' THEN
        init_guard_true_2 <= init_guard_true_1;
      END IF;
    END IF;
  END PROCESS matching_delays_process;


  outinit_guard_default_re <= to_signed(16#00000#, 18);
  outinit_guard_default_im <= to_signed(16#00000#, 18);

  -- Count limited, Unsigned Counter
  --  initial value   = 0
  --  step value      = 1
  --  count to value  = 5597
  count_step <= to_unsigned(16#0001#, 13);

  count_from <= to_unsigned(16#0000#, 13);

  count_reset <= to_unsigned(16#0000#, 13);

  count <= HDL_Counter_out1 + count_step;

  
  need_to_wrap <= '1' WHEN HDL_Counter_out1 = to_unsigned(16#15DD#, 13) ELSE
      '0';

  
  count_value <= count WHEN need_to_wrap = '0' ELSE
      count_from;

  
  count_1 <= HDL_Counter_out1 WHEN enb_1 = '0' ELSE
      count_value;

  
  count_2 <= count_1 WHEN rst = '0' ELSE
      count_reset;

  HDL_Counter_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out1 <= to_unsigned(16#0000#, 13);
      ELSIF enb_1_32_0 = '1' THEN
        HDL_Counter_out1 <= count_2;
      END IF;
    END IF;
  END PROCESS HDL_Counter_process;


  
  prelookup_idx_sat <= to_unsigned(16#0000#, 13) WHEN HDL_Counter_out1 = to_unsigned(16#0000#, 13) ELSE
      to_unsigned(16#15DD#, 13) WHEN HDL_Counter_out1 >= to_unsigned(16#15DD#, 13) ELSE
      HDL_Counter_out1;

  
  prelookup_idx <= to_unsigned(16#15DD#, 13) WHEN prelookup_idx_sat > to_unsigned(16#15DD#, 13) ELSE
      prelookup_idx_sat;

  realOut <= alpha1_D_Lookup_Table_table_data(to_integer(prelookup_idx));

  PipelineRegister_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF enb_1_32_0 = '1' THEN
        realOut_1 <= realOut;
      END IF;
    END IF;
  END PROCESS PipelineRegister_process;


  imagOut <= alpha1_D_Lookup_Table_table_data_2(to_integer(prelookup_idx));

  PipelineRegister_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF enb_1_32_0 = '1' THEN
        imagOut_1 <= imagOut;
      END IF;
    END IF;
  END PROCESS PipelineRegister_1_process;


  
  alpha1_D_Lookup_Table_out1_re <= outinit_guard_default_re WHEN init_guard_true_2 = '0' ELSE
      realOut_1;
  
  alpha1_D_Lookup_Table_out1_im <= outinit_guard_default_im WHEN init_guard_true_2 = '0' ELSE
      imagOut_1;

  Out1_re <= std_logic_vector(alpha1_D_Lookup_Table_out1_re);

  Out1_im <= std_logic_vector(alpha1_D_Lookup_Table_out1_im);

  
  Compare_To_Constant_out1 <= '1' WHEN HDL_Counter_out1 = to_unsigned(16#15DC#, 13) ELSE
      '0';

  endOfLUT <= Compare_To_Constant_out1;

END rtl;

